<script setup>
import { computed, ref } from 'vue'
import { useRouter } from 'vue-router'
import { useDreamJourney, today } from '../composables/useDreamJourney'
import { useJourneyUi } from '../composables/useJourneyUi'
import BedtimeRelaxation from './BedtimeRelaxation.vue'
const router=useRouter(),{journals,plan,commit}=useDreamJourney(),{save,toast}=useJourneyUi()
const active=ref(2),busy=ref(false),drafts=ref({})
const bedtime=ref(plan.value.bedtime),wake=ref(plan.value.wake),started=ref(plan.value.started||today())
const lessons=[
 {id:'notice',name:'认识自己的睡眠',title:'先认识自己的夜晚',intro:'不急着给睡眠打分。留意真实的感受，慢慢认识自己的节奏。',habits:['凭印象记录入睡时刻，不必夜里反复看钟','留意醒来后的身体感受，允许每天不同','回看白天的活动，发现属于自己的线索','偶尔睡不好也没关系，不用责怪自己'],exercise:'留下一个发现',prompt:'最近的夜晚，有什么让你印象深刻？一个词、一句话，都可以。',tip:'记录是为了了解自己，不是追求一张完美的成绩单。'},
 {id:'room',name:'整理睡眠环境',title:'给夜晚留一个舒服的角落',intro:'从光线、声音与温度里，挑一处愿意调整的小细节，不必一次做到所有。',habits:['调暗明亮的灯，留一盏柔和的小夜灯','把工作通知暂时静音，给夜晚留一点空间','调整被子与枕头，让身体舒服地被承托','找到适合自己的声音与温度，不必添置设备'],exercise:'整理一处小角落',prompt:'今晚，你想让哪个小细节更舒服一点？写下一个愿意尝试的改变。',tip:'舒服的环境没有标准答案，适合你的感受就好。'},
 {id:'rhythm',name:'建立日常节律',title:'建立温柔的节律',intro:'允许自己慢慢来，不急着改变，也不强迫立刻睡着。从今天起，为身体建立一些可预测的小信号。',habits:['固定起床时间，给清晨一个明朗的开始','白天接触自然光，帮助身体校准节律','午后减少咖啡因，让夜晚更容易安静下来','睡前一小时降低屏幕刺激，准备进入休息状态'],exercise:'节律重置',prompt:'选一个你能做到的小改变，写下来，并告诉自己：我愿意用温柔的节奏，重新安排夜晚。',tip:'不用一次做很多。稳定的小习惯，比偶尔的大改变更有力量。'},
 {id:'release',name:'释放白天压力',title:'把白天的疲惫慢慢放下',intro:'今天没解决的事情，不必都带到枕边。允许自己暂时停下，先照顾此刻。',habits:['写下一句心事，暂时把它放在纸上','轻轻松开肩膀，自然呼吸，不必追赶节拍','听一段轻音乐，让注意力慢慢落回身边','给自己一句肯定，今天已经做了很多'],exercise:'给今天一个温柔的句号',prompt:'有没有一句话，想对忙了一天的自己说？不想写，也可以只在心里默念。',tip:'放松也不是任务。任何时候觉得不舒服，都可以停下。'}
]
const lesson=computed(()=>lessons[active.value])
const note=computed({get:()=>drafts.value[lesson.value.id]??plan.value.lessonNotes?.[lesson.value.id]??'',set:v=>drafts.value[lesson.value.id]=v})
// Stable namespaced keys keep earlier numeric completion records intact.
const marked=computed(()=>plan.value.lessonActions||[])
const recordDays=computed(()=>new Set(journals.value.map(j=>j.date)).size)
async function toggle(i){if(busy.value)return;busy.value=true;const key=lesson.value.id+':'+i;try{await save(commit,'plan',{...plan.value,lessonActions:marked.value.includes(key)?marked.value.filter(x=>x!==key):[...marked.value,key]})}finally{busy.value=false}}
async function saveNote(){if(busy.value)return;busy.value=true;const id=lesson.value.id,value=note.value;try{await save(commit,'plan',{...plan.value,lessonNotes:{...plan.value.lessonNotes,[id]:value}},'这一句已保存，可以随时回来修改')}finally{busy.value=false}}
async function saveSchedule(){if(!bedtime.value||!wake.value||!started.value||busy.value)return;busy.value=true;try{await save(commit,'plan',{...plan.value,bedtime:bedtime.value,wake:wake.value,started:started.value},'作息心愿已保存')}finally{busy.value=false}}
</script>
<template>
 <div class="sleep-course">
  <section class="course-strip"><button aria-label="返回梦境首页" @click="router.push('/dream')">←</button><p>可以试着练习 7 天，观察身体和情绪的变化。漏一天也没关系。</p><small>{{recordDays}} 天已记录　{{marked.length}} 个小行动已尝试</small></section>
  <div class="course-layout">
   <aside class="j-panel course-sidebar"><h2>建立温柔的节律</h2><div class="course-tabs" role="group" aria-label="睡眠课程"><button v-for="(item,i) in lessons" :key="item.id" :aria-pressed="active===i" :class="{chosen:active===i}" @click="active=i"><span class="lesson-number">{{i+1}}</span><span><small>第{{i+1}}节</small>{{item.name}}</span></button></div><details class="course-settings"><summary>作息心愿设置</summary><label>心愿入睡时刻<input v-model="bedtime" type="time"></label><label>心愿起床时刻<input v-model="wake" type="time"></label><label>开始日期<input v-model="started" type="date"></label><button :disabled="busy||!bedtime||!wake||!started" @click="saveSchedule">保存我的节律</button><button @click="router.push('/dream/sleep-diary')">回看睡眠日记</button></details></aside>
   <div class="course-main">
    <section class="j-panel course-lesson"><h2>{{lesson.title}}</h2><p class="course-intro">{{lesson.intro}}</p>
     <div class="habit-grid"><button v-for="(habit,i) in lesson.habits" :key="lesson.id+i" class="habit-card" :class="{marked:marked.includes(lesson.id+':'+i)}" :aria-pressed="marked.includes(lesson.id+':'+i)" :disabled="busy" @click="toggle(i)">
      <svg viewBox="0 0 72 72" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><template v-if="i===0"><rect x="19" y="12" width="34" height="46" rx="4" fill="#fcfbff"/><path d="M25 21h11m-11 7h20m-20 7h15"/><path d="m51 43 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z" fill="#eee8c9" stroke="none"/></template><template v-else-if="i===1"><circle cx="36" cy="36" r="21" fill="#faf9ed"/><circle cx="36" cy="36" r="12"/><path d="M36 6v5m0 50v5M6 36h5m50 0h5M14 14l4 4m36 36 4 4m0-44-4 4M18 54l-4 4"/></template><template v-else-if="i===2"><path d="M20 22h29v27a9 9 0 0 1-9 9H29a9 9 0 0 1-9-9Z" fill="#f3edf7"/><path d="M49 27h5a8 8 0 0 1 0 16h-5M27 10v5m10-7v7M17 62h38"/></template><template v-else><rect x="23" y="10" width="28" height="49" rx="5" fill="#f2f0f7"/><path d="M32 16h10M34 53h6M14 45 58 21"/><path d="m54 8 2 4 4 1-3 3v4l-3-2-4 2 1-4-3-3 4-1Z" fill="#e7e0ee" stroke="none"/></template></g></svg>
      <span>{{habit}}</span><small>{{marked.includes(lesson.id+':'+i)?'已尝试 · 点击取消':'愿意时，点一下记录尝试'}}</small>
     </button></div>
     <div class="exercise-row"><div class="course-exercise"><h3>本节练习：{{lesson.exercise}}</h3><p>{{lesson.prompt}}</p><details><summary>写下我的小改变</summary><label><span class="j-sr">本节练习记录</span><textarea v-model="note" rows="2" maxlength="500" placeholder="一句就好，不想写也可以留白。"></textarea></label><button :disabled="busy" @click="saveNote">保存这一句</button><small>保存在当前账号，可随时修改或清空后保存。</small></details></div><aside class="course-tip"><h3>小提示</h3><p>{{lesson.tip}}</p></aside></div>
    </section>
    <BedtimeRelaxation id="bedtime-relax" compact />
   </div>
  </div><div v-if="toast" class="j-toast" role="status">{{toast}}</div>
 </div>
</template>
<style scoped>
.sleep-course{color:#494052}.course-strip{display:flex;align-items:center;gap:24px;padding:14px 24px;background:#fffdfef5;border:1px solid #e8e1ed;border-radius:24px;margin-bottom:20px}.course-strip button{border:0;background:transparent;font-size:27px;padding:0 10px}.course-strip p{flex:1;margin:0;color:#807687;font-size:14px}.course-strip small{white-space:nowrap}.course-layout{display:grid;grid-template-columns:250px minmax(0,1fr);gap:20px;align-items:stretch}.course-sidebar.j-panel,.course-lesson.j-panel{margin:0;border-radius:28px;background:#fffffff2;border:1px solid #e7e0eb;padding:26px;box-shadow:0 3px 12px #6e587006}.course-sidebar h2{font-size:23px;margin:0 0 28px;padding-bottom:26px;border-bottom:1px solid #eeebf0}.course-tabs{display:grid;gap:10px}.course-tabs button{display:flex;align-items:center;gap:12px;min-height:76px;padding:14px;text-align:left;border:1px solid #e4dfe8;border-radius:16px;background:#fff;color:#5e526a}.course-tabs .chosen{background:#f0eaf8;border-color:#c9b9da}.lesson-number{display:grid;place-items:center;width:22px;height:25px;flex:none;border:1px solid #c3b7cd;border-radius:8px;font-size:12px}.course-tabs small{margin-right:8px;font-size:13px;color:#8c8196}.course-settings{margin-top:30px;color:#82758f;font-size:13px}.course-settings label{margin-top:14px}.course-settings button{margin-top:12px;width:100%}.course-main{min-width:0;display:grid;gap:20px;align-content:start}.course-lesson h2{font-size:26px;margin:0 0 14px}.course-intro{font-size:15px;line-height:1.8;margin:0 0 24px}.habit-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.habit-card{display:flex;flex-direction:column;align-items:flex-start;text-align:left;border:1px solid #e7e3ec;border-radius:20px;padding:18px 16px;background:#faf9fc;color:#54475f;font-size:15px;line-height:1.7}.habit-card:nth-child(2){background:#fdfcf7}.habit-card svg{width:60px;height:60px;align-self:center;margin-bottom:12px;color:#89739e}.habit-card small{font-size:11px;color:#908697;margin-top:10px}.habit-card.marked{border-color:#aa95bd;background:#f1ebf7}.exercise-row{display:grid;grid-template-columns:minmax(0,1fr) 215px;gap:20px;margin-top:22px}.course-exercise{border-top:1px solid #e9e4ed;padding-top:18px}.course-exercise h3{font:500 23px/1.5 SimSun,serif;margin:0 0 14px}.course-exercise p{font-size:15px;line-height:1.8}.course-exercise details{font-size:13px;color:#877494}.course-exercise textarea{margin:12px 0}.course-exercise details small{display:block;font-size:12px;margin-top:8px}.course-tip{align-self:end;padding:20px;border:1px solid #e5eee6;background:#f2faf3;border-radius:20px}.course-tip h3{font-size:19px;margin:0 0 10px}.course-tip p{font-size:14px;line-height:1.8;margin:0}summary{cursor:pointer;min-height:30px}button:focus-visible,summary:focus-visible{outline:2px solid #9a80b4;outline-offset:3px}
@media(max-width:1200px){.course-layout{grid-template-columns:210px minmax(0,1fr)}.course-sidebar.j-panel,.course-lesson.j-panel{padding:22px}.habit-grid{gap:10px}.habit-card{padding:15px 12px}.exercise-row{grid-template-columns:minmax(0,1fr) 185px}}
@media(max-width:1000px){.course-layout{grid-template-columns:1fr}.course-tabs{grid-template-columns:repeat(4,minmax(0,1fr))}.course-sidebar h2{margin-bottom:15px;padding-bottom:15px}.course-tabs button{padding:10px;gap:8px}.course-tabs small{display:block}.course-settings{margin-top:16px}.course-strip{flex-wrap:wrap;gap:10px}.course-strip p{flex-basis:75%}}
@media(max-width:600px){.course-strip{padding:14px}.course-strip small{margin-left:12px;font-size:12px;white-space:normal}.course-tabs{grid-template-columns:1fr 1fr}.course-sidebar.j-panel,.course-lesson.j-panel{padding:20px 16px;border-radius:23px}.habit-grid{grid-template-columns:1fr 1fr}.habit-card{font-size:14px}.exercise-row{grid-template-columns:1fr}.course-tip{padding:16px}.course-lesson h2{font-size:23px}}
</style>
